UPDATE payment p
JOIN subscription s ON p.Subscription_ID = s.Subscription_ID
SET p.Created_Time = CAST(CONCAT(s.Start_Date, ' 08:00:00') AS DATETIME)
WHERE p.Payment_Type = 'Subscription';